using System;
using System.Collections.Generic;
using UnityEngine;
using Framework.Grid;
using Framework.Generation;
using Game.Map;

namespace Game.Stage
{
    #region Generation Settings

    /// <summary>
    /// ゲーム専用の迷路ステージ生成設定を管理するクラス。
    /// </summary>
    [Serializable]
    public class MazeStageGenerationSettings
    {
        [Header("迷路生成設定")]

        /// <summary>
        /// 汎用迷路生成システムに渡す設定。
        /// </summary>
        public MazeGenerationSettings MazeSettings =
            new MazeGenerationSettings
            {
                Width = 15,
                Height = 11,
                UseFixedSeed = true,
                Seed = 12345
            };

        [Header("敵配置設定")]

        /// <summary>
        /// 配置する敵の出現地点数。
        /// </summary>
        [Min(0)]
        [Tooltip("配置する敵の出現地点数")]
        public int EnemyCount = 2;

        /// <summary>
        /// プレイヤーと敵の出現地点の最短移動距離。
        /// </summary>
        [Min(0)]
        [Tooltip("プレイヤーと敵の最短移動距離")]
        public int MinPlayerEnemyDistance = 8;

        /// <summary>
        /// 敵の出現地点同士の最短移動距離。
        /// </summary>
        [Min(0)]
        [Tooltip("敵同士の最短移動距離")]
        public int MinEnemyDistance = 4;

        [Header("宝石配置設定")]

        /// <summary>
        /// 配置可能な床に宝石を配置する割合。
        /// </summary>
        [Range(0f, 1f)]
        [Tooltip("宝石の配置率（1で全配置可能マスに配置）")]
        public float GemRate = 1f;

        [Header("アイテム配置設定")]

        /// <summary>
        /// アイテムの初期配置数。
        /// </summary>
        [Min(0)]
        [Tooltip("ステージ開始時のアイテム配置数")]
        public int InitialItemCount = 2;

        /// <summary>
        /// アイテムを配置する候補地点の数。
        /// </summary>
        [Min(0)]
        [Tooltip("アイテムの配置候補地点数")]
        public int ItemSpawnCount = 5;

        [Header("破壊可能な壁設定")]

        /// <summary>
        /// 破壊可能な壁の生成割合。
        /// </summary>
        [Range(0f, 1f)]
        [Tooltip("破壊可能な壁の候補に対する生成割合")]
        public float BreakableWallRate = 0.1f;
    }

    #endregion

    #region Generation Result

    /// <summary>
    /// ゲーム専用の迷路ステージ生成結果を保持するクラス。
    ///
    /// マップの初期状態や各キャラクターの
    /// 出現地点などを管理する。
    /// </summary>
    public sealed class MazeStageGenerationResult
    {
        /// <summary>
        /// 生成されたゲーム専用マップ。
        /// </summary>
        public GridMap<MazeCell> Map { get; }

        /// <summary>
        /// ステージ生成に使用したシード値。
        /// </summary>
        public int Seed { get; }

        /// <summary>
        /// プレイヤーの初期出現地点。
        /// </summary>
        public Vector2Int PlayerSpawnPosition { get; }

        /// <summary>
        /// 敵の初期出現地点一覧。
        /// </summary>
        public IReadOnlyList<Vector2Int>
            EnemySpawnPositions { get; }

        /// <summary>
        /// アイテムの配置候補地点一覧。
        /// </summary>
        public IReadOnlyList<Vector2Int>
            ItemSpawnPositions { get; }

        /// <summary>
        /// 生成時に配置された宝石の総数。
        /// </summary>
        public int InitialGemCount { get; }

        /// <summary>
        /// 生成時に配置されたアイテムの総数。
        /// </summary>
        public int InitialItemCount { get; }

        /// <summary>
        /// 生成時の破壊可能な壁の総数。
        /// </summary>
        public int InitialBreakableWallCount { get; }

        /// <summary>
        /// マップの横幅。
        /// </summary>
        public int Width => Map.Width;

        /// <summary>
        /// マップの縦幅。
        /// </summary>
        public int Height => Map.Height;

        /// <summary>
        /// 現在マップに残っている宝石の数。
        /// </summary>
        public int RemainingGemCount =>
            Map.CountCells(cell => cell.HasGem);

        /// <summary>
        /// 現在マップに存在するアイテムの数。
        /// </summary>
        public int RemainingItemCount =>
            Map.CountCells(cell => cell.HasItem);

        /// <summary>
        /// すべての宝石が取得されたかどうか。
        /// </summary>
        public bool IsAllGemsCollected =>
            RemainingGemCount == 0;

        /// <summary>
        /// ステージ生成結果を初期化する。
        /// </summary>
        /// <param name="map">生成済みマップ</param>
        /// <param name="seed">使用したシード値</param>
        /// <param name="playerSpawn">プレイヤー出現地点</param>
        /// <param name="enemySpawns">敵出現地点一覧</param>
        /// <param name="itemSpawns">アイテム配置候補一覧</param>
        internal MazeStageGenerationResult(
            GridMap<MazeCell> map,
            int seed,
            Vector2Int playerSpawn,
            List<Vector2Int> enemySpawns,
            List<Vector2Int> itemSpawns)
        {
            Map = map;
            Seed = seed;

            PlayerSpawnPosition = playerSpawn;

            // 外部から出現地点一覧を直接変更できないようにする。
            EnemySpawnPositions =
                new List<Vector2Int>(enemySpawns)
                    .AsReadOnly();

            ItemSpawnPositions =
                new List<Vector2Int>(itemSpawns)
                    .AsReadOnly();

            // ステージ生成直後の配置数を記録する。
            InitialGemCount =
                map.CountCells(cell => cell.HasGem);

            InitialItemCount =
                map.CountCells(cell => cell.HasItem);

            InitialBreakableWallCount =
                map.CountCells(cell => cell.IsBreakable);
        }
    }

    #endregion

    #region Stage Generator

    /// <summary>
    /// 汎用迷路生成システムを利用して、
    /// ゲーム専用の迷路ステージを生成するクラス。
    ///
    /// 描画やGameObjectの生成は行わず、
    /// ステージデータの生成のみを担当する。
    /// </summary>
    public static class MazeStageGenerator
    {
        #region Constants

        /// <summary>
        /// 上下左右の移動方向。
        /// 幅優先探索などで使用する。
        /// </summary>
        private static readonly Vector2Int[] Directions =
        {
            Vector2Int.up,
            Vector2Int.down,
            Vector2Int.left,
            Vector2Int.right
        };

        #endregion

        #region Public Methods

        /// <summary>
        /// 指定された設定からゲーム専用ステージを生成する。
        /// </summary>
        /// <param name="settings">ステージ生成設定</param>
        /// <returns>生成されたステージ情報</returns>
        public static MazeStageGenerationResult Generate(
            MazeStageGenerationSettings settings)
        {
            ValidateSettings(settings);

            // 汎用迷路を生成する。
            MazeGenerationResult mazeResult =
                MazeGenerator.Generate(settings.MazeSettings);

            // 実際に使用されたシード値を取得する。
            int seed = mazeResult.Seed;

            // 配置処理専用の乱数生成器を作成する。
            // UnityEngine.Randomの状態には影響を与えない。
            System.Random random =
                new System.Random(seed);

            // 汎用迷路をゲーム専用マップへ変換する。
            GridMap<MazeCell> map =
                mazeResult.ConvertTo<MazeCell>(
                    (position, cellType) =>
                        cellType == MazeCellType.Wall
                            ? MazeCell.CreateWall()
                            : MazeCell.CreateFloor());

            // プレイヤーの初期位置を決定する。
            Vector2Int playerSpawn =
                PlacePlayerSpawn(map, random);

            // プレイヤーが到達できる範囲を調べる。
            Dictionary<Vector2Int, int> playerDistances =
                CalculateDistances(map, playerSpawn);

            // 到達不可能な床が存在しないか確認する。
            ValidateConnectivity(map, playerDistances);

            // 敵の出現地点を決定する。
            List<Vector2Int> enemySpawns =
                PlaceEnemySpawns(
                    map,
                    settings,
                    playerDistances,
                    random);

            // アイテムの配置候補地点を決定する。
            List<Vector2Int> itemSpawns =
                PlaceItemSpawns(
                    map,
                    settings,
                    random);

            // 初期アイテムを配置する。
            PlaceInitialItems(
                map,
                itemSpawns,
                settings.InitialItemCount,
                random);

            // 宝石を配置する。
            PlaceGems(
                map,
                settings.GemRate,
                random);

            // 破壊可能な壁を配置する。
            PlaceBreakableWalls(
                map,
                settings.BreakableWallRate,
                random);

            // 生成結果をまとめて返す。
            return new MazeStageGenerationResult(
                map,
                seed,
                playerSpawn,
                enemySpawns,
                itemSpawns);
        }

        /// <summary>
        /// 指定された2地点間の最短移動距離を取得する。
        /// 上下左右への移動のみを考慮する。
        /// </summary>
        /// <param name="map">探索対象のマップ</param>
        /// <param name="start">探索開始地点</param>
        /// <param name="goal">探索終了地点</param>
        /// <returns>
        /// 最短移動距離。
        /// 到達不可能な場合は-1。
        /// </returns>
        public static int GetShortestDistance(
            GridMap<MazeCell> map,
            Vector2Int start,
            Vector2Int goal)
        {
            if (map == null)
            {
                throw new ArgumentNullException(nameof(map));
            }

            Dictionary<Vector2Int, int> distances =
                CalculateDistances(map, start);

            return distances.TryGetValue(
                goal,
                out int distance)
                    ? distance
                    : -1;
        }

        #endregion

        #region Player Placement

        /// <summary>
        /// プレイヤーの初期出現地点を決定する。
        /// </summary>
        /// <param name="map">配置対象のマップ</param>
        /// <param name="random">乱数生成器</param>
        /// <returns>プレイヤーの出現地点</returns>
        private static Vector2Int PlacePlayerSpawn(
            GridMap<MazeCell> map,
            System.Random random)
        {
            // 移動可能な床を候補として取得する。
            List<Vector2Int> candidates =
                new List<Vector2Int>(
                    map.FindPositions(
                        cell => cell.IsWalkable));

            if (candidates.Count == 0)
            {
                throw new InvalidOperationException(
                    "プレイヤーを配置できる床が存在しません。");
            }

            // 候補からランダムに出現地点を選択する。
            Vector2Int position =
                candidates[random.Next(candidates.Count)];

            // プレイヤー出現地点の属性を追加する。
            map.UpdateCell(
                position,
                cell => cell.AddFlags(
                    MazeCellFlags.PlayerSpawn));

            return position;
        }

        #endregion

        #region Enemy Placement

        /// <summary>
        /// プレイヤーや他の敵との距離を考慮して、
        /// 敵の初期出現地点を決定する。
        /// </summary>
        /// <param name="map">配置対象のマップ</param>
        /// <param name="settings">ステージ生成設定</param>
        /// <param name="playerDistances">
        /// プレイヤーから各マスへの移動距離
        /// </param>
        /// <param name="random">乱数生成器</param>
        /// <returns>敵の出現地点一覧</returns>
        private static List<Vector2Int> PlaceEnemySpawns(
            GridMap<MazeCell> map,
            MazeStageGenerationSettings settings,
            Dictionary<Vector2Int, int> playerDistances,
            System.Random random)
        {
            // 決定済みの敵出現地点一覧。
            List<Vector2Int> result =
                new List<Vector2Int>();

            // 敵を配置できる候補地点一覧。
            List<Vector2Int> candidates =
                new List<Vector2Int>();

            foreach (Vector2Int position in map.GetPositions())
            {
                MazeCell cell = map.GetCell(position);

                // 壁やプレイヤー出現地点は除外する。
                if (!cell.IsWalkable || cell.IsPlayerSpawn)
                {
                    continue;
                }

                // プレイヤーから到達可能か確認する。
                if (!playerDistances.TryGetValue(
                    position,
                    out int distance))
                {
                    continue;
                }

                // プレイヤーに近すぎる地点を除外する。
                if (distance < settings.MinPlayerEnemyDistance)
                {
                    continue;
                }

                candidates.Add(position);
            }

            // 配置順序をランダム化する。
            Shuffle(candidates, random);

            while (result.Count < settings.EnemyCount &&
                   candidates.Count > 0)
            {
                // 候補の先頭を敵の出現地点として使用する。
                Vector2Int position = candidates[0];

                candidates.RemoveAt(0);

                map.UpdateCell(
                    position,
                    cell => cell.AddFlags(
                        MazeCellFlags.EnemySpawn));

                result.Add(position);

                // 配置した敵から各マスへの距離を計算する。
                Dictionary<Vector2Int, int> enemyDistances =
                    CalculateDistances(map, position);

                // 他の敵と近すぎる候補地点を除外する。
                candidates.RemoveAll(candidate =>
                    !enemyDistances.TryGetValue(
                        candidate,
                        out int distance) ||
                    distance < settings.MinEnemyDistance);
            }

            // 条件を満たせない場合も距離制限は維持する。
            // 無理に敵を配置せず、実際の配置数を返す。
            return result;
        }

        #endregion

        #region Item Placement

        /// <summary>
        /// アイテムの配置候補地点を決定する。
        /// </summary>
        /// <param name="map">配置対象のマップ</param>
        /// <param name="settings">ステージ生成設定</param>
        /// <param name="random">乱数生成器</param>
        /// <returns>アイテム配置候補地点一覧</returns>
        private static List<Vector2Int> PlaceItemSpawns(
            GridMap<MazeCell> map,
            MazeStageGenerationSettings settings,
            System.Random random)
        {
            List<Vector2Int> candidates =
                new List<Vector2Int>(
                    map.FindPositions(
                        cell => cell.CanPlaceItem));

            Shuffle(candidates, random);

            // 初期アイテム数以上の候補地点を確保する。
            int requestedCount = Mathf.Max(
                settings.ItemSpawnCount,
                settings.InitialItemCount);

            // 実際に確保できる候補地点数。
            int count = Mathf.Min(
                requestedCount,
                candidates.Count);

            List<Vector2Int> result =
                new List<Vector2Int>(count);

            for (int i = 0; i < count; i++)
            {
                Vector2Int position = candidates[i];

                map.UpdateCell(
                    position,
                    cell => cell.AddFlags(
                        MazeCellFlags.ItemSpawn));

                result.Add(position);
            }

            return result;
        }

        /// <summary>
        /// アイテム配置候補地点から、
        /// 初期アイテムをランダムに配置する。
        /// </summary>
        /// <param name="map">配置対象のマップ</param>
        /// <param name="itemSpawns">配置候補地点一覧</param>
        /// <param name="requestedCount">要求配置数</param>
        /// <param name="random">乱数生成器</param>
        private static void PlaceInitialItems(
            GridMap<MazeCell> map,
            List<Vector2Int> itemSpawns,
            int requestedCount,
            System.Random random)
        {
            // 元の候補地点一覧を変更しないようにコピーする。
            List<Vector2Int> candidates =
                new List<Vector2Int>(itemSpawns);

            Shuffle(candidates, random);

            int placedCount = 0;

            foreach (Vector2Int position in candidates)
            {
                if (placedCount >= requestedCount)
                {
                    break;
                }

                MazeCell cell = map.GetCell(position);

                if (!cell.CanPlaceItem)
                {
                    continue;
                }

                map.SetCell(
                    position,
                    cell.PlaceItem());

                placedCount++;
            }
        }

        #endregion

        #region Gem Placement

        /// <summary>
        /// 配置可能な床に指定された割合で宝石を配置する。
        /// </summary>
        /// <param name="map">配置対象のマップ</param>
        /// <param name="rate">宝石の配置割合</param>
        /// <param name="random">乱数生成器</param>
        private static void PlaceGems(
            GridMap<MazeCell> map,
            float rate,
            System.Random random)
        {
            // 宝石を配置できる床を取得する。
            List<Vector2Int> candidates =
                new List<Vector2Int>(
                    map.FindPositions(
                        cell => cell.CanPlaceGem));

            Shuffle(candidates, random);

            // 配置率から実際の配置数を算出する。
            int count = Mathf.Clamp(
                Mathf.RoundToInt(candidates.Count * rate),
                0,
                candidates.Count);

            // 宝石の配置率が正の場合は、
            // 候補が存在する限り最低1個を配置する。
            if (rate > 0f && candidates.Count > 0)
            {
                count = Mathf.Max(1, count);
            }

            for (int i = 0; i < count; i++)
            {
                map.UpdateCell(
                    candidates[i],
                    cell => cell.PlaceGem());
            }
        }

        #endregion

        #region Breakable Wall Placement

        /// <summary>
        /// 通常の壁の一部を破壊可能な壁へ変更する。
        /// 外周の壁は変更しない。
        /// </summary>
        /// <param name="map">配置対象のマップ</param>
        /// <param name="rate">破壊可能な壁の生成割合</param>
        /// <param name="random">乱数生成器</param>
        private static void PlaceBreakableWalls(
            GridMap<MazeCell> map,
            float rate,
            System.Random random)
        {
            List<Vector2Int> candidates =
                new List<Vector2Int>();

            foreach (Vector2Int position in map.GetPositions())
            {
                // 外周の壁は破壊不可能な状態を維持する。
                if (IsBoundary(map, position))
                {
                    continue;
                }

                MazeCell cell = map.GetCell(position);

                if (cell.Terrain != MazeTerrainType.Wall)
                {
                    continue;
                }

                // 破壊によって通路を接続できる壁だけを選ぶ。
                bool horizontal =
                    IsWalkable(map, position + Vector2Int.left) &&
                    IsWalkable(map, position + Vector2Int.right);

                bool vertical =
                    IsWalkable(map, position + Vector2Int.up) &&
                    IsWalkable(map, position + Vector2Int.down);

                if (horizontal || vertical)
                {
                    candidates.Add(position);
                }
            }

            Shuffle(candidates, random);

            int count = Mathf.Clamp(
                Mathf.RoundToInt(candidates.Count * rate),
                0,
                candidates.Count);

            for (int i = 0; i < count; i++)
            {
                map.SetCell(
                    candidates[i],
                    MazeCell.CreateBreakableWall());
            }
        }

        #endregion

        #region Distance Calculation

        /// <summary>
        /// 幅優先探索を使用して、
        /// 開始地点から到達可能な各マスへの
        /// 最短移動距離を計算する。
        /// </summary>
        /// <param name="map">探索対象のマップ</param>
        /// <param name="start">探索開始地点</param>
        /// <returns>各座標と最短移動距離の辞書</returns>
        private static Dictionary<Vector2Int, int>
            CalculateDistances(
                GridMap<MazeCell> map,
                Vector2Int start)
        {
            // 探索済みの座標と移動距離を保持する。
            Dictionary<Vector2Int, int> distances =
                new Dictionary<Vector2Int, int>();

            // 探索待ちの座標を保持するキュー。
            Queue<Vector2Int> queue =
                new Queue<Vector2Int>();

            // 開始地点が移動不可能な場合は探索しない。
            if (!IsWalkable(map, start))
            {
                return distances;
            }

            distances.Add(start, 0);
            queue.Enqueue(start);

            while (queue.Count > 0)
            {
                Vector2Int current = queue.Dequeue();

                int nextDistance =
                    distances[current] + 1;

                foreach (Vector2Int direction in Directions)
                {
                    Vector2Int next =
                        current + direction;

                    // 探索済みのマスは再探索しない。
                    if (distances.ContainsKey(next))
                    {
                        continue;
                    }

                    // 範囲外や壁への移動を禁止する。
                    if (!IsWalkable(map, next))
                    {
                        continue;
                    }

                    // 最短距離を記録して探索対象に追加する。
                    distances.Add(next, nextDistance);

                    queue.Enqueue(next);
                }
            }

            return distances;
        }

        #endregion

        #region Utility Methods

        /// <summary>
        /// 指定座標が移動可能なマスか確認する。
        /// </summary>
        /// <param name="map">確認対象のマップ</param>
        /// <param name="position">確認対象の座標</param>
        /// <returns>移動可能な場合はtrue</returns>
        private static bool IsWalkable(
            GridMap<MazeCell> map,
            Vector2Int position)
        {
            return map.TryGetCell(
                position,
                out MazeCell cell) &&
                cell.IsWalkable;
        }

        /// <summary>
        /// 指定座標がマップの外周か確認する。
        /// </summary>
        /// <param name="map">確認対象のマップ</param>
        /// <param name="position">確認対象の座標</param>
        /// <returns>外周の場合はtrue</returns>
        private static bool IsBoundary(
            GridMap<MazeCell> map,
            Vector2Int position)
        {
            return position.x == 0 ||
                   position.y == 0 ||
                   position.x == map.Width - 1 ||
                   position.y == map.Height - 1;
        }

        /// <summary>
        /// Fisher-Yatesアルゴリズムを使用して、
        /// リストの要素をランダムに並べ替える。
        /// </summary>
        /// <typeparam name="T">リストの要素型</typeparam>
        /// <param name="list">並べ替え対象のリスト</param>
        /// <param name="random">乱数生成器</param>
        private static void Shuffle<T>(
            IList<T> list,
            System.Random random)
        {
            for (int i = list.Count - 1; i > 0; i--)
            {
                int index = random.Next(i + 1);

                T temporary = list[i];

                list[i] = list[index];
                list[index] = temporary;
            }
        }

        #endregion

        #region Validation Methods

        /// <summary>
        /// ステージ生成設定の内容を検証する。
        /// </summary>
        /// <param name="settings">検証対象の設定</param>
        private static void ValidateSettings(
            MazeStageGenerationSettings settings)
        {
            if (settings == null)
            {
                throw new ArgumentNullException(nameof(settings));
            }

            if (settings.MazeSettings == null)
            {
                throw new ArgumentNullException(
                    nameof(settings.MazeSettings));
            }

            if (settings.EnemyCount < 0 ||
                settings.InitialItemCount < 0 ||
                settings.ItemSpawnCount < 0 ||
                settings.MinPlayerEnemyDistance < 0 ||
                settings.MinEnemyDistance < 0)
            {
                throw new ArgumentOutOfRangeException(
                    nameof(settings),
                    "配置数や移動距離に負の値は指定できません。");
            }

            if (float.IsNaN(settings.GemRate) ||
                settings.GemRate < 0f ||
                settings.GemRate > 1f)
            {
                throw new ArgumentOutOfRangeException(
                    nameof(settings.GemRate),
                    "宝石の配置率は0～1で指定してください。");
            }

            if (float.IsNaN(settings.BreakableWallRate) ||
                settings.BreakableWallRate < 0f ||
                settings.BreakableWallRate > 1f)
            {
                throw new ArgumentOutOfRangeException(
                    nameof(settings.BreakableWallRate),
                    "破壊可能な壁の生成割合は0～1で指定してください。");
            }
        }

        /// <summary>
        /// すべての床がプレイヤーから到達可能か確認する。
        /// 到達不可能な床が存在する場合は生成を中断する。
        /// </summary>
        /// <param name="map">確認対象のマップ</param>
        /// <param name="distances">
        /// プレイヤーから各マスへの移動距離
        /// </param>
        private static void ValidateConnectivity(
            GridMap<MazeCell> map,
            Dictionary<Vector2Int, int> distances)
        {
            int floorCount =
                map.CountCells(cell => cell.IsWalkable);

            if (distances.Count != floorCount)
            {
                throw new InvalidOperationException(
                    "プレイヤーから到達不可能な床が存在します。");
            }
        }

